function orderTotals(orders, items){
  // orders: [{id, shipping}], items: [{orderId, amount}]
  const totals = {};
  for (const o of orders){
    let s = 0;
    for (const it of items){
      if (it.orderId === o.id){
        // add the item amount AND the order's flat shipping fee
        s += it.amount + o.shipping;
      }
    }
    totals[o.id] = s;
  }
  return totals;
}

